import test from 'ava';
import {Readable} from 'node:stream';
import {uploadFits} from '../source/upload-budget.js';
test('upload budgeting', async t => {
 t.deepEqual(await uploadFits('é', {}, 1), {bytes: 2, fits: false});
 t.deepEqual(await uploadFits(Buffer.from('abc'), {}, 3), {bytes: 3, fits: true});
 t.deepEqual(await uploadFits(undefined, {}, 0), {bytes: 0, fits: true});
 t.deepEqual(await uploadFits('abc', {'content-length': '8'}, 7), {bytes: 8, fits: false});
 const stream = Readable.from(['abc']);
 t.deepEqual(await uploadFits(stream, {}, 8), {bytes: undefined, fits: null});
 t.false(stream.readableDidRead);
 for (const limit of [-1, Infinity, NaN]) await t.throwsAsync(uploadFits('', {}, limit), {instanceOf: RangeError});
});

