+import getBodySize from './core/utils/get-body-size.js';
+import type {ClientRequestArgs} from 'node:http';
+
+export async function uploadFits(body: unknown, headers: ClientRequestArgs['headers'], limit: number) {
+	if (!Number.isFinite(limit) || limit < 0) throw new RangeError('Invalid byte budget');
+	const bytes = await getBodySize(body, headers);
+	return {bytes, fits: bytes === undefined ? null : bytes <= limit};
+}

