import test from 'ava';
import {EventEmitter} from 'node:events';
import {relayTransfer} from '../source/transfer-relay.js';
test('transfer relay lifecycle', t => {
 const a = new EventEmitter(), b = new EventEmitter();
 const seen: unknown[] = []; let closed = 0; let own = 0;
 a.on('uploadProgress', () => own++);
 for (const name of ['uploadProgress', 'downloadProgress', 'error', 'other']) b.on(name, (...args) => seen.push([name, ...args]));
 const dispose = relayTransfer(a, b, () => closed++);
 const error = new Error('network');
 a.emit('uploadProgress', 1, 2); a.emit('downloadProgress', {n: 3}); a.emit('error', error); a.emit('other', 1);
 t.deepEqual(seen, [['uploadProgress', 1, 2], ['downloadProgress', {n: 3}], ['error', error]]);
 dispose(); dispose(); a.emit('uploadProgress', 5);
 t.is(seen.length, 3); t.is(own, 2); t.is(closed, 1); t.is(a.listenerCount('error'), 0);
 const stop = relayTransfer(a, b, () => closed++); stop(); t.is(closed, 2);
});

