+import type {EventEmitter} from 'node:events';
+import proxyEvents from './core/utils/proxy-events.js';
+
+export function relayTransfer(source: EventEmitter, destination: EventEmitter, onClose: () => void) {
+	const detach = proxyEvents(source, destination, ['uploadProgress', 'downloadProgress', 'error']);
+	let closed = false;
+	return () => {
+		if (closed) return;
+		closed = true;
+		detach();
+		onClose();
+	};
+}

