import test from 'ava';
import {EventEmitter} from 'node:events';
import {watchOutcome} from '../source/first-outcome.js';
test('first outcome and cancellation', t => {
 for (const event of ['response', 'error']) {
  const e = new EventEmitter(); const seen: unknown[] = []; const own = () => {};
  e.on('error', own);
  const cancel = watchOutcome(e, (...args) => seen.push(args));
  const payload = {ok: true}; e.emit(event, payload); e.emit('response', 2); e.emit('error', 3); cancel();
  t.deepEqual(seen, [[event, payload]]); t.is(e.listenerCount('response'), 0); t.deepEqual(e.listeners('error'), [own]);
 }
 const e = new EventEmitter(); let called = false;
 const cancel = watchOutcome(e, () => {called = true;}); cancel(); cancel(); e.emit('response');
 t.false(called); t.is(e.listenerCount('error'), 0);
});

