@@ -0,0 +1,13 @@
+import type {EventEmitter} from 'node:events';
+import unhandle from './core/utils/unhandle.js';
+
+export function watchOutcome(emitter: EventEmitter, callback: (event: string, payload: unknown) => void) {
+	const listeners = unhandle();
+	for (const event of ['response', 'error']) {
+		listeners.once(emitter, event, (payload: unknown) => {
+			listeners.unhandleAll();
+			callback(event, payload);
+		});
+	}
+	return () => listeners.unhandleAll();
+}

