+import parseLinkHeader from './core/parse-link-header.js';
+
+export function paginationTarget(header: string | undefined, currentUrl: string, relation: string) {
+	if (!header?.trim()) return null;
+	for (const link of parseLinkHeader(header)) {
+		const relations = (link.parameters.rel ?? '').replace(/^"|"$/g, '').split(/\s+/);
+		if (relations.includes(relation)) return new URL(link.reference, currentUrl).href;
+	}
+	return null;
+}

