from click.option_badge import option_badge


def test_badge():
    values = ["--verbose", "-v", "/V", "plain", "--version"]
    assert option_badge(values, "LEVEL") == {"text": "plain, -v, /V, --verbose, --version LEVEL", "windows_style": True}
    assert values[0] == "--verbose"
    assert option_badge(["--foo", "-f"]) == {"text": "-f, --foo", "windows_style": False}
    assert option_badge([], "X") == {"text": "", "windows_style": False}
    assert option_badge(["-x"], "") == {"text": "-x", "windows_style": False}

from click.completion_cursor import completion_cursor


def test_cursor():
    assert completion_cursor("run 'my file") == {"complete": ["run"], "current": "my file"}
    assert completion_cursor('run "my file" ') == {"complete": ["run", "my file"], "current": ""}
    assert completion_cursor("run my\\") == {"complete": ["run"], "current": "my"}
    assert completion_cursor("run #tag") == {"complete": ["run"], "current": "#tag"}
    assert completion_cursor("") == {"complete": [], "current": ""}
    assert completion_cursor("   ") == {"complete": [], "current": ""}

import functools
import pytest
from _pytest.default_manifest import default_manifest


def test_defaults():
    def sample(a=1, /, b=2, *args, c=3, d, **kwargs):
        pass
    @functools.wraps(sample)
    def wrapped(*args, **kwargs):
        pass
    assert default_manifest([wrapped]) == {"sample": ["b", "c"]}
    def empty(x):
        pass
    assert default_manifest([empty]) == {"empty": []}
    assert default_manifest([]) == {}
    class Invalid:
        __name__ = "broken"
        __signature__ = 42
        def __call__(self):
            pass
    with pytest.raises(TypeError):
        default_manifest([Invalid()])

