import pytest
from _pytest.fixture_contract import fixture_contract


def test_contract():
    def sample(a, /, b, c=1, *args, d, e=2, **kwargs):
        pass
    assert fixture_contract(sample) == {"name": "sample", "required": ["b", "d"]}
    class Suite:
        def method(self, resource, optional=1):
            pass
        @staticmethod
        def static(resource):
            pass
    assert fixture_contract(Suite.method, Suite)["required"] == ["resource"]
    assert fixture_contract(Suite.static, Suite)["required"] == ["resource"]
    @patch("os.getcwd")
    def mocked(mock_getcwd, resource):
        pass
    assert fixture_contract(mocked)["required"] == ["resource"]
    def empty():
        pass
    assert fixture_contract(empty)["required"] == []
    empty.__signature__ = 42
    with pytest.raises(pytest.fail.Exception):
        fixture_contract(empty)

import pytest
from _pytest.plugin_metadata import plugin_metadata


def test_metadata():
    class Plugin:
        zero = 0
        blank = ""
        @property
        def broken(self):
            raise ValueError("bad descriptor")
        @property
        def skipped(self):
            pytest.skip("not available")
        @property
        def interrupted(self):
            raise KeyboardInterrupt()
    plugin = Plugin()
    sentinel = object()
    assert plugin_metadata(plugin, ["zero", "blank", "missing", "broken", "skipped"], sentinel) == {"zero": 0, "blank": "", "missing": sentinel, "broken": sentinel, "skipped": sentinel}
    assert plugin_metadata(plugin, []) == {}
    with pytest.raises(KeyboardInterrupt):
        plugin_metadata(plugin, ["interrupted"])
